def get_age_node(state):
    q = state.get("pending_question") or "What is your age?"
    answer = interrupt(q)
    if isinstance(answer, int) and answer > 0:
        return {"age": answer, "pending_question": None}
    return {"pending_question": f"'{answer}' is not a valid age."}

