def send_email(to: str, subject: str, body: str):
    response = interrupt({"action": "send_email", "to": to})
    if response.get("action") == "approve":
        s = response.get("subject", subject)
        b = response.get("body", body)
        return f"Sent '{s}': {b}"
    return "Email cancelled by user"

